import java.util.Arrays;

/**
 * A sample controller to demonstrate the usage of ResponseMapper.
 */
@RestController
public class SampleController {

    @GetMapping("/success")
    public ResponseEntity<StandardResponse<int[]>> getSuccessResponse() {
