```javascript
const fs = require('fs');
const axios = require('axios');
const Docxtemplater = require('docxtemplater');

// Function to fetch resume data from GraphQL endpoint
async function fetchResumeData() {
    try {
        const response = await axios.post('YOUR_GRAPHQL_ENDPOINT', {
            query: `
                query {
                    // Your GraphQL query to fetch resume data
                }
            `
        });

        return response.data.data; // Assuming your data is under "data" key in the response
    } catch (error) {
        console.error('Error fetching resume data:', error);
        throw error;
    }
}

// Function to generate DOCX file using resume data
async function generateResumeDocx() {
    try {
        const resumeData = await fetchResumeData();

        // Load the template file
        const templateContent = fs.readFileSync('resume_template.docx', 'binary');
        const docx = new Docxtemplater();
        docx.loadZip(templateContent);

        // Set the resume data to fill in the placeholders
        docx.setData(resumeData);
        docx.render();

        // Save the generated DOCX file
        const buffer = docx.getZip().generate({ type: 'nodebuffer' });
