If you want to show hours only in the day view and hide them in the month and week views, you can conditionally render the hourly sections based on the selected view. Here's the modified `renderCalendar` function:

```jsx
const renderCalendar = () => {
  let startDate, endDate;

  switch (view) {
    case "week":
      startDate = startOfWeek(date);
      endDate = endOfWeek(date);
      break;
    case "day":
      startDate = startOfDay(date);
      endDate = endOfDay(date);
      break;
    default:
      startDate = startOfMonth(date);
      endDate = endOfMonth(date);
      break;
  }

  const calendarDays = [];
  let currentDate = startDate;

  // Check if the view is "day" to render hourly sections
  const isDayView = view === "day";

  while (currentDate <= endDate) {
    calendarDays.push({ date: currentDate, dayOfMonth: currentDate.getDate() });
    // Add hourly sections only in the day view
    if (isDayView) {
      currentDate = addHours(currentDate, 1);
    } else {
      currentDate = addDays(currentDate, 1);
    }
  }

  return (
    <div className="calendar">
      <div className="calendar-header">
        <button onClick={() => setDate(subMonths(date, 1))}>&lt;</button>
        <h2>{format(date, view === "month" ? "MMMM yyyy" : view === "week" ? "MMMM yyyy, w" : "MMMM d, yyyy")}</h2>
        <button onClick={() => setDate(addMonths(date, 1))}>&gt;</button>
        <div className="view-buttons">
          <button onClick={() => setView("month")} className={view === "month" ? "active" : ""}>Month</button>
          <button onClick={() => setView("week")} className={view === "week" ? "active" : ""}>Week</button>
          <button onClick={() => setView("day")} className={view === "day" ? "active" : ""}>Day</button>
        </div>
      </div>
      <div className="calendar-body">
        {isDayView ? (
