export const selectTopicsData = (state) => state.topics.data;

// Helper method to get the next topic ID
export const getNextTopicId = (increment = 1) => (state) => {
  const topicsData = selectTopicsData(state);
  if (topicsData.length === 0) {
    return null; // No topics available
  }
  const lastIndex = topicsData.length - 1;
  const lastTopicId = topicsData[lastIndex].id;
  return lastTopicId + increment;
};

